module PLL (
    input wire clk_in,
    input wire [3:0] control_signal,
    output reg clk_out
);
    reg [3:0] vco_freq;
    reg [3:0] divider;
    reg [7:0] counter;

    always @(posedge clk_in) begin
        vco_freq <= control_signal; // Control VCO frequency based on the control signal
        counter <= counter + 1; // Increment counter
        if (counter >= (8'd255 / vco_freq)) begin // Frequency division logic
            clk_out <= ~clk_out; // Toggle output clock 
            counter <= 0; // Reset counter
        end
    end

    initial begin
        clk_out = 0;
        counter = 0;
    end
endmodule

