module pipeline_register (
    input wire clk,
    input wire rst,
    input wire [7:0] data_in,
    output reg [7:0] data_out
);
    reg [7:0] stage [0:6]; // 7 stages of registers

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset all pipeline stages
            stage[0] <= 8'b0;
            stage[1] <= 8'b0;
            stage[2] <= 8'b0;
            stage[3] <= 8'b0;
            stage[4] <= 8'b0;
            stage[5] <= 8'b0;
            stage[6] <= 8'b0;
            data_out <= 8'b0;
        end else begin
            // Shift data through the stages
            stage[0] <= data_in;
            stage[1] <= stage[0];
            stage[2] <= stage[1];
            stage[3] <= stage[2];
            stage[4] <= stage[3];
            stage[5] <= stage[4];
            stage[6] <= stage[5];
            data_out <= stage[6];
        end
    end
endmodule

