        if (rst) begin
            state <= 128'b0;
            ciphertext <= 128'b0;
            done <= 1'b0;
            round <= 0;
        end else if (start) begin
            // Initial round key addition
            state <= plaintext ^ key;
            round <= 0;
            done <= 1'b0;
        end else if (round <= NUM_ROUNDS) begin
            // Implement AES rounds here
