module dma_controller(  
    input clk,  
    input reset,  
    input [7:0] request, // Each bit represents a transfer request from a channel  
    output reg [7:0] grant, // Each bit represents a granted channel  
    output reg busy,  
    input [7:0] data_in,  
    output reg [7:0] data_out  
);  

    reg [2:0] state; // State variable  
    reg [2:0] next_state;  

    localparam IDLE = 3'b000,  
               GRANT = 3'b001,  
               TRANSFER = 3'b010,  
               DONE = 3'b011;  

    always @(posedge clk or posedge reset) begin  
        if (reset)  
            state <= IDLE;  
        else  
            state <= next_state;  
    end  

    always @(*) begin  
        case (state)  
            IDLE: begin  
                busy = 0;  
                if (request != 8'b0) begin  
                    grant = request;  
                    next_state = GRANT;  
                end else begin  
                    grant = 8'b0;  
                    next_state = IDLE;  
                end  
            end  
            GRANT: begin  
                busy = 1;  
                next_state = TRANSFER;  
            end  
            TRANSFER: begin  
                data_out = data_in & grant; // Simulate data transfer  
                next_state = DONE;  
            end  
            DONE: begin  
                busy = 0;  
                grant = 8'b0;  
                next_state = IDLE;  
            end  
            default: next_state = IDLE;  
        endcase  
    end  
endmodule

