module audio_frame_buffer (
    input clk,
    input reset,
    input process,
    input [15:0] new_sample,
    output reg [15:0] avg_sample
);
    reg [15:0] samples [0:4]; // Buffer for 5 samples
    integer i;
    integer sum;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Clear buffer and output
            for (i = 0; i < 5; i = i + 1) begin
                samples[i] <= 16'b0;
            end
            avg_sample <= 16'b0;
        end else begin
            // Shift samples and add new sample
            for (i = 0; i < 4; i = i + 1) begin
                samples[i] <= samples[i + 1];
            end
            samples[4] <= new_sample; // Add new sample

            // Calculate average if process signal is asserted
            if (process) begin
                sum = 0;
                for (i = 0; i < 5; i = i + 1) begin
                    sum = sum + samples[i];
                end
                avg_sample <= sum / 5; // Average calculation
            end
        end
    end
endmodule

