module cordic_sine_cosine (
    input clk,
    input rst,
    input [15:0] angle, // Fixed point angle in radians (Q1.15)
    input start,
    output reg [15:0] sine,
    output reg [15:0] cosine,
    output reg done
);
    parameter NUM_ITER = 16;
    reg [15:0] x, y, z;
    reg [3:0] iter;
    reg [15:0] atan_table [0:NUM_ITER-1];

    initial begin
        // Initialize atan_table with precomputed arctangents
        atan_table[0] = 16'h3243;  // atan(1) in Q1.15
        atan_table[1] = 16'h1DAC;  // atan(0.5) in Q1.15
        // Fill in other values...
        atan_table[2] = 16'h1A3D;
        atan_table[3] = 16'h0FAD;
        atan_table[4] = 16'h07E4;
        // Continue this up to NUM_ITER - 1
        // ...
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            x <= 16'h4000;  // 1 in Q1.15
            y <= 16'h0000;  // 0 in Q1.15
            z <= angle;
            iter <= 0;
            done <= 0;
        end else if (start && !done) begin
            if (iter < NUM_ITER) begin
                if (z < 0) begin
                    // Perform rotation in the negative direction
                    x <= x + (y >>> iter);
                    y <= y - (x >>> iter);
                    z <= z + atan_table[iter];
                end else begin
                    // Perform rotation in the positive direction
                    x <= x - (y >>> iter);
                    y <= y + (x >>> iter);
                    z <= z - atan_table[iter];
                end
                iter <= iter + 1;
            end else begin
                sine <= y;
                cosine <= x;
                done <= 1;
            end
        end
    end
endmodule

