module dma_controller(
    input clk,
    input reset,
    input [7:0] source_addr,
    input [7:0] dest_addr,
    input start,
    input stop,
    output reg busy,
    output reg complete
);
    reg [1:0] state;

    localparam IDLE = 2'b00;
    localparam TRANSFER = 2'b01;
    localparam DONE = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            busy <= 0;
            complete <= 0;
        end else begin
            case (state)
                IDLE: begin
                    busy <= 0;
                    complete <= 0;
                    if (start) begin
                        state <= TRANSFER;
                        busy <= 1;
                    end
                end
                TRANSFER: begin
                    // Simulate data transfer logic
                    // Normally here we would actually transfer data
                    state <= DONE;
                end
                DONE: begin
                    busy <= 0;
                    complete <= 1;
                    if (stop) begin
                        state <= IDLE;
                    end
                end
            endcase
        end
    end
endmodule

