    always @(posedge CLK or negedge EN) begin  
        if (!EN) begin  
            master <= 0;  
            slave <= 0;  
        end else begin  
            master <= D;  
        end  
    end  

    always @(negedge CLK or negedge EN) begin  
        if (!EN) begin  
            Q <= 0;  
        end else begin  
            Q <= master;  
        end  
    end  
endmodule

